<?php
use App\Http\Controllers\Rider\RiderController;use Illuminate\Support\Facades\Route;
Route::prefix('rider')->name('rider.')->middleware(['auth','role:rider'])->group(function(){Route::get('dashboard',[RiderController::class,'dashboard'])->name('dashboard');Route::get('shipments/{shipment}',[RiderController::class,'show'])->name('shipments.show');Route::post('shipments/{shipment}/status',[RiderController::class,'status'])->name('shipments.status');Route::post('shipments/{shipment}/cod-collection',[RiderController::class,'collectCod'])->name('shipments.cod-collection');Route::post('shipments/{shipment}/location',[RiderController::class,'location'])->middleware('throttle:12,1')->name('shipments.location');Route::post('shipments/{shipment}/pod',[RiderController::class,'pod'])->name('shipments.pod');});
